import { apps, icon, robot, experience, projects, skills, certifications, principles } from './content.js';
import { missions } from './missions.js';
import { readProgress, completeMission } from './progress.mjs';

const $=s=>document.querySelector(s);
const storage={get(k){try{return localStorage.getItem(k)}catch{return null}},set(k,v){try{localStorage.setItem(k,v)}catch{}}};
let lang=storage.get('rafaelos-language')==='es'?'es':'en';
let completed=readProgress(storage.get('rafaelos-missions'));
let z=10,activeId=null,botIndex=0;
const windows=new Map();
const compactLayout=()=>matchMedia('(max-width: 1024px), (max-height: 600px)').matches;
const game={mission:null,choice:null,finished:false};
const t=(en,es)=>lang==='es'?es:en;
const p=pair=>pair[lang==='es'?1:0];
const app=id=>apps.find(a=>a.id===id);
const label=id=>app(id)[lang];
const button=(id,title,primary=false)=>`<button class="btn ${primary?'primary':''}" data-open="${id}">${icon(app(id).icon)}${title}</button>`;
const tags=items=>items.map(x=>`<span class="tag">${x}</span>`).join('');
const pdf=()=>`<a class="btn" href="Rafael-Rendon-Resume.pdf" download>${icon('document')}${t('Download PDF','Descargar PDF')}</a>`;
const timeline=()=>experience.map(e=>`<article class="timeline-entry"><time>${p(e.date)}</time><h2>${e.company}</h2><h3>${p(e.role)}</h3><small class="timeline-place">${p(e.place)}</small><ul>${e.points.map(x=>`<li>${p(x)}</li>`).join('')}</ul></article>`).join('');
function home(){return `<div class="home"><p class="eyebrow">${t('TECHNICAL SUPPORT. HUMAN TOUCH.','SOPORTE TÉCNICO. TOQUE HUMANO.')}</p><div class="home-top"><div><h1>${t('Hi, I’m Rafael.<br>I make things<br><strong>work again.</strong>','Hola, soy Rafael.<br>Hago que todo<br><strong>vuelva a funcionar.</strong>')}</h1><p class="intro">${t('From autonomous robots to trading platforms. <br>I investigate the unexpected, connect the dots, <br>and automate the <b>“not this again.”</b>','De robots autónomos a plataformas de trading. <br>Investigo lo inesperado, conecto las pistas <br>y automatizo el <b>“otra vez esto no”.</b>')}</p></div><div class="profile-art"><div class="avatar-frame"><div class="avatar-inner">${robot()}</div></div><span>${t('Your friendly system troubleshooter.','Tu aliado para resolver problemas.')}</span></div></div><div class="hero-actions">${button('experience',t('Explore my experience','Ver mi experiencia'),true)}${button('resume',t('Read my resume','Leer mi currículum'))}</div><div class="info-strip"><span><i class="live-dot"></i>${t('Based in Bogotá, Colombia','Desde Bogotá, Colombia')}</span><span>◉ ${t('English + Spanish','Inglés + Español')}</span><span>⌘ ${t('TechOps & Automation','TechOps y automatización')}</span></div><div class="launch-section"><div class="section-label"><span>${t('A few things to open','Unas cosas para explorar')}</span><span>${t('Go on. Click around.','Adelante. Explora.')}</span></div><div class="launch-grid">${[
 ['game',t('Take a shift with me','Comparte mi turno'),t('3 incidents. One curious mind.','3 incidentes. Una mente curiosa.')],
 ['projects',t('Visit the automation lab','Visita el laboratorio'),t('Less repetition. More possibility.','Menos repetición. Más posibilidades.')],
 ['contact',t('Let’s build something','Construyamos algo'),t('Good conversations start here.','Las buenas conversaciones empiezan aquí.')]
 ].map(([id,title,sub])=>`<button class="launch-card" data-open="${id}">${icon(app(id).icon)}<span class="arrow">↗</span><strong>${title}</strong><small>${sub}</small></button>`).join('')}</div></div><div class="home-footer">${t('Powered by curiosity. Occasionally restarted with coffee.','Funciona con curiosidad. A veces se reinicia con café.')}</div></div>`}
function about(){return `<div class="page"><p class="eyebrow">${t('SYSTEM PROPERTIES / THE HUMAN','PROPIEDADES DEL SISTEMA / EL HUMANO')}</p><h1>Rafael Angel<br>Rendon Tasama</h1><p class="lead">${t('Technical Support Engineer · Mechatronics background<br>Bogotá, Colombia · Spanish (native), English (C1 / professional)','Ingeniero de soporte técnico · Formación en mecatrónica<br>Bogotá, Colombia · Español nativo, inglés C1 / profesional')}</p><div class="about-banner">${t('I work where finance, infrastructure and people meet. My favorite fix is the one we don’t have to repeat.','Trabajo donde se encuentran las finanzas, la infraestructura y las personas. Mi solución favorita es la que no tenemos que repetir.')}</div><p class="lead">${t('My path has taken me from global e-commerce to autonomous robots and fintech operations. I trace problems through logs, telemetry and API behavior, then translate the findings into clear next steps for customers and engineers.','Mi trayectoria va del comercio electrónico global a los robots autónomos y la operación fintech. Sigo las pistas en logs, telemetría y APIs, y convierto los hallazgos en pasos claros para clientes y desarrolladores.')}</p><h2>${t('How I work','Cómo trabajo')}</h2>${principles.map((x,i)=>`<div class="principle"><b>0${i+1}</b><p>${p(x)}</p></div>`).join('')}<h2>${t('Education','Educación')}</h2><p class="lead">Universidad Autónoma de Occidente<br>${t('Mechatronics, Robotics & Automation Engineering','Mecatrónica, Robótica e Ingeniería de Automatización')}<br>Cali, Colombia · 2019–2024</p><h2>${t('Certifications','Certificaciones')}</h2>${certifications.map(c=>`<div class="bin-item">${c}</div>`).join('')}</div>`}
function contact(){return `<div class="page"><p class="eyebrow">${t('NEW CONNECTION','NUEVA CONEXIÓN')}</p><h1>${t('Let’s talk.','Hablemos.')}</h1><p class="lead">${t('A tricky system, a thoughtful team, or an interesting opportunity?<br>I’d love to hear about it.','¿Un sistema complejo, un buen equipo o una oportunidad interesante?<br>Me encantaría conocerla.')}</p>${[
 ['mail',t('EMAIL','CORREO'),'angetazama20@gmail.com','mailto:angetazama20@gmail.com'],
 ['globe','LINKEDIN','in/sinfolonokojo','https://www.linkedin.com/in/sinfolonokojo'],
 ['terminal','GITHUB','github.com/sinfolonokojo','https://github.com/sinfolonokojo'],
 ['user',t('PHONE · COLOMBIA','TELÉFONO · COLOMBIA'),'+57 313 664 8312','tel:+573136648312']
 ].map(([ic,name,value,url])=>`<a class="contact-row" href="${url}" ${url.startsWith('https')?'target="_blank" rel="noopener noreferrer"':''}>${icon(ic)}<div><small>${name}</small><strong>${value}</strong></div><span class="external">↗</span></a>`).join('')}<div class="about-banner">${t('Based in Bogotá · UTC−5<br>Spanish and English. Comfortable collaborating across time zones.','Desde Bogotá · UTC−5<br>Español e inglés. Experiencia colaborando entre zonas horarias.')}</div>${pdf()}</div>`}
function resume(){return `<div class="page"><div class="resume-header"><p class="eyebrow">${t('THE CLASSIC VERSION','LA VERSIÓN CLÁSICA')}</p><h1>Rafael Angel Rendon Tasama</h1><p>${t('Technical Support Engineer · TechOps · Fintech & Robotics','Ingeniero de soporte técnico · TechOps · Fintech y robótica')}</p><p>Colombia · angetazama20@gmail.com · +57 313 664 8312</p><div class="hero-actions">${pdf()}${button('contact',t('Contact me','Contáctame'))}</div></div><section class="resume-section"><h2>${t('Profile','Perfil')}</h2><p>${t('Technical Support Engineer with a Mechatronics background, specializing in complex system diagnostics and sustainable resolutions. Experienced across robotics, fintech and e-commerce, with Python automation and a “fix it once” approach to documentation and repeat work.','Ingeniero de soporte técnico con formación en mecatrónica, especializado en diagnóstico de sistemas complejos y soluciones sostenibles. Experiencia en robótica, fintech y comercio electrónico, con automatización en Python y documentación para evitar trabajo repetitivo.')}</p><h2>${t('Experience','Experiencia')}</h2>${timeline()}<h2>${t('Selected projects','Proyectos destacados')}</h2>${projects.map(proj=>`<p><b>${p(proj.title)}</b> · ${p(proj.date)}<br>${p(proj.body)}</p>`).join('')}<h2>${t('Technical skills','Habilidades técnicas')}</h2>${skills.map(([name,items])=>`<p><b>${p(name)}:</b> ${items.join(', ')}</p>`).join('')}<h2>${t('Education','Educación')}</h2><p>Universidad Autónoma de Occidente · Cali<br>${t('Mechatronics, Robotics & Automation Engineering','Mecatrónica, Robótica e Ingeniería de Automatización')} · 2019–2024</p><h2>${t('Certifications','Certificaciones')}</h2><p>${certifications.join('<br>')}</p><h2>${t('Languages','Idiomas')}</h2><p>${t('Spanish: native · English: C1 / professional proficiency','Español: nativo · Inglés: C1 / competencia profesional')}</p></section></div>`}
function gamePage(){
 const count=completed.length;
 if(game.mission===null)return `<div class="page"><p class="eyebrow">${t('RAFAELOS / SHIFT SIMULATOR','RAFAELOS / SIMULADOR DE TURNO')}</p><h1>${t('Your shift starts now.','Tu turno empieza ahora.')}</h1><p class="lead">${t('Three small mysteries. Follow the evidence, choose your next step, and see how I think through a problem. No technical exam. Coffee optional.','Tres pequeños misterios. Sigue la evidencia, elige el siguiente paso y descubre cómo analizo un problema. Sin examen técnico. Café opcional.')}</p><div class="game-meta"><span>${t('Shift progress','Progreso del turno')}</span><span>${count} / 3 ${t('resolved','resueltos')}</span></div><div class="progress-track"><i class="progress-${count}"></i></div><div class="mission-grid">${missions.map((m,i)=>`<button class="mission-card" data-mission="${i}"><span class="mission-number">${completed.includes(i)?'✓':'0'+(i+1)}</span><div><strong>${p(m.title)}</strong><small>${p(m.domain)}</small></div><span class="arrow">→</span></button>`).join('')}</div><p class="fiction">${t('Fictional training scenarios inspired by my fields of work. All logs, figures and situations below are invented.','Escenarios ficticios inspirados en mis áreas de trabajo. Los logs, cifras y situaciones son inventados.')}</p>${count===3?`<div class="feedback good">${t('Shift complete. Evidence collected, people informed, coffee earned.','Turno completado. Evidencia recopilada, personas informadas y café merecido.')}</div>`:''}${count?`<button class="btn" data-action="reset-progress">${t('Reset shift progress','Reiniciar progreso')}</button>`:''}</div>`;
 const m=missions[game.mission];
 if(game.finished)return `<div class="page"><div class="completion">${icon('badge')}<p class="eyebrow mission-eyebrow">${t('INCIDENT DOCUMENTED','INCIDENTE DOCUMENTADO')}</p><h1>${t('That’s a good handover.','Una buena entrega de turno.')}</h1><p>${t('The next person gets the evidence, the reasoning and the next step. That’s how one investigation becomes reusable knowledge.','La siguiente persona recibe la evidencia, el razonamiento y el próximo paso. Así una investigación se convierte en conocimiento reutilizable.')}</p></div><div class="about-banner"><b>${t('How this connects to my work','Cómo se conecta con mi trabajo')}</b><br>${p(m.lesson)}</div><div class="mission-footer"><button class="btn primary" data-action="mission-list">${t('Back to the shift','Volver al turno')}</button>${button('experience',t('Explore my experience','Ver mi experiencia'))}</div></div>`;
 const good=game.choice===m.correct;
 return `<div class="page"><div class="game-meta"><span>${t('Fictional incident','Incidente ficticio')} 0${game.mission+1}</span><button class="btn mission-back" data-action="mission-list">← ${t('All missions','Misiones')}</button></div><h1 class="mission-title">${p(m.title)}</h1><p class="lead">${p(m.story)}</p><pre class="clues">${p(m.clues)}</pre><h2>${p(m.question)}</h2><div class="choices">${m.choices.map((c,i)=>`<button class="choice" data-choice="${i}" ${good?'disabled':''}>${String.fromCharCode(65+i)}. ${p(c[0])}</button>`).join('')}</div>${game.choice!==null?`<div class="feedback ${good?'good':''}" role="status">${p(m.choices[game.choice][1])}${!good?`<br><b>${t('Try another approach.','Prueba otro enfoque.')}</b>`:''}</div>`:''}${good?`<button class="btn primary" data-action="finish-mission">${t('Document it & hand it over →','Documentar y entregar →')}</button>`:''}</div>`;
}
function content(view){switch(view){
 case 'home':return home();
 case 'experience':return `<div class="page"><p class="eyebrow">${t('MY EXPERIENCE / CAREER HISTORY','MI EXPERIENCIA / TRAYECTORIA')}</p><h1>${t('Different systems.<br>Same curiosity.','Distintos sistemas.<br>La misma curiosidad.')}</h1><p class="lead">${t('E-commerce, autonomous robotics, and fintech.<br>A career built around understanding what went wrong—and what comes next.','Comercio electrónico, robótica autónoma y fintech.<br>Una trayectoria enfocada en entender qué falló y cuál es el siguiente paso.')}</p>${timeline()}</div>`;
 case 'projects':return `<div class="page"><p class="eyebrow">${t('AUTOMATION LAB / SELECTED WORK','LABORATORIO / PROYECTOS')}</p><h1>${t('Teach the system.<br>Free the human.','Enseñarle al sistema.<br>Liberar a la persona.')}</h1><p class="lead">${t('Small tools that make repeat work a little less repetitive. Here’s what I’ve built and what I’m building.','Herramientas para hacer menos repetitivo el trabajo. Esto es lo que he desarrollado y lo que estoy construyendo.')}</p>${projects.map(pr=>`<article class="project"><div class="project-head"><h2>${p(pr.title)}</h2><span class="pill ${pr.wip?'wip':''}">${p(pr.status)}</span></div><p>${p(pr.body)}</p>${tags(pr.tags)}<div class="project-date"><small>${p(pr.date)}</small></div></article>`).join('')}<p class="fiction">${t('Support tools are described at a high level; proprietary code and customer data are not included.','Las herramientas internas se describen de forma general; no se incluye código propietario ni datos de clientes.')}</p><a class="btn" href="https://github.com/sinfolonokojo" target="_blank" rel="noopener noreferrer">${icon('terminal')}${t('Visit my GitHub','Visita mi GitHub')} ↗</a></div>`;
 case 'skills':return `<div class="page"><p class="eyebrow">${t('MY TOOLBOX / WORKING KNOWLEDGE','HERRAMIENTAS / CONOCIMIENTOS')}</p><h1>${t('The tools behind the fix.','Las herramientas detrás de la solución.')}</h1><p class="lead">${t('From the first signal to an actionable explanation.','Desde la primera señal hasta una explicación útil.')}</p>${skills.map(([name,items])=>`<section class="skill-group"><h2>${p(name)}</h2>${tags(items)}</section>`).join('')}<h2>${t('Working languages','Idiomas de trabajo')}</h2><p class="lead">${t('Spanish · Native<br>English · C1 / professional proficiency','Español · Nativo<br>Inglés · C1 / competencia profesional')}</p></div>`;
 case 'about':return about(); case 'contact':return contact(); case 'resume':return resume(); case 'game':return gamePage();
 case 'recycle':return `<div class="page"><p class="eyebrow">${t('RECYCLE BIN / RETIRED BAD HABITS','PAPELERA / MALOS HÁBITOS RETIRADOS')}</p><h1>${t('Some things can stay deleted.','Algunas cosas pueden seguir borradas.')}</h1><div class="recycle-art">${icon('bin')}</div>${['it_works_on_my_machine.txt','restart_everything.bat','final_FINAL_v2_really_final.docx'].map(x=>`<div class="bin-item">${x}</div>`).join('')}<p class="empty">${t('Restore? Let’s not.','¿Restaurar? Mejor no.')}</p><div class="about-banner">${t('The actual files are safe. These are just jokes.<br>The real fix belongs in a runbook.','Los archivos reales están a salvo. Estos son solo chistes.<br>La solución real merece una guía.')}</div>${button('projects',t('See the useful stuff','Ver lo útil'),true)}</div>`;
 }}
function sidebar(view){return `<aside class="sidebar"><p class="sidebar-heading">${t('Favorites','Favoritos')}</p>${apps.filter(a=>!['recycle','contact'].includes(a.id)).map(a=>`<button data-nav="${a.id}" class="${view===a.id?'selected':''}" aria-label="${a[lang]}" ${view===a.id?'aria-current="page"':''}>${icon(a.icon)}<span>${a[lang]}</span></button>`).join('')}<div class="sidebar-bottom"><span class="live-dot"></span>RafaelOS Personal<br>${t('Curiosity is connected.','Curiosidad conectada.')}<br>© ${new Date().getFullYear()} Rafael Rendon</div></aside>`}
function renderWindow(w){const a=app(w.view);w.el.innerHTML=`<header class="titlebar">${icon(a.icon)}<span class="window-title">${a[lang]} — RafaelOS</span><div class="window-controls"><button data-control="minimize" aria-label="${t('Minimize','Minimizar')}">−</button><button data-control="maximize" aria-label="${t('Maximize or restore','Maximizar o restaurar')}">□</button><button data-control="close" class="close" aria-label="${t('Close window','Cerrar ventana')}">×</button></div></header><div class="window-shell"><div class="explorer-bar"><button class="back-button" data-nav="home" aria-label="${t('Go to Welcome Center','Ir a Bienvenida')}">‹</button><div class="address">${icon('computer')}<span class="crumb-root">RafaelOS</span><span class="breadcrumb-sep">›</span><b>${a[lang]}</b></div><span class="explorer-note">${t('A little window into my world','Una ventana a mi mundo')}</span></div><div class="window-interior">${sidebar(w.view)}<div class="content">${content(w.view)}</div></div><div class="statusbar"><span>${t('Technical Support Engineer · TechOps','Ingeniero de soporte técnico · TechOps')}</span><span>${t('Evidence before assumptions.','Evidencia antes de suposiciones.')}</span></div></div>`;w.el.setAttribute('aria-label',a[lang]);renderTasks()}
function open(view){const exists=[...windows.values()].find(w=>w.view===view);if(exists){activate(exists.id);return}const id='win-'+Date.now()+'-'+windows.size;const el=document.createElement('section');el.className='window';el.id=id;el.setAttribute('role','region');el.tabIndex=-1;$('#windows').append(el);const w={id,view,el,minimized:false,max:false};windows.set(id,w);renderWindow(w);activate(id);if(windows.size>1&&!compactLayout()){const count=(windows.size-1)%4;el.style.top=`${8+count*3}%`;el.style.marginLeft=`${count*15}px`}el.focus({preventScroll:true});$('#announcement').textContent=label(view)+' '+t('opened','abierto')}
function activate(id){const w=windows.get(id);if(!w)return;w.minimized=false;w.el.classList.remove('hidden');w.el.style.zIndex=++z;activeId=id;for(const v of windows.values())v.el.classList.toggle('active',v.id===id);renderTasks()}
function nextActive(){const top=[...windows.values()].filter(v=>!v.minimized).sort((a,b)=>Number(b.el.style.zIndex)-Number(a.el.style.zIndex))[0];activeId=null;if(top)activate(top.id);else renderTasks()}
function renderTasks(){if(!$('#tasks'))return;$('#tasks').innerHTML=[...windows.values()].map(w=>`<button class="task ${activeId===w.id&&!w.minimized?'active':''}" data-task="${w.id}" aria-label="${label(w.view)}" aria-pressed="${activeId===w.id&&!w.minimized}">${icon(app(w.view).icon)}<span>${label(w.view)}</span></button>`).join('')}
function minimize(w){w.minimized=true;w.el.classList.add('hidden');w.el.classList.remove('active');nextActive()}
function renderGame(){for(const w of windows.values())if(w.view==='game'){const scroll=w.el.querySelector('.content').scrollTop;renderWindow(w);w.el.querySelector('.content').scrollTop=scroll}}
function setStart(show){$('#start-menu').hidden=!show;$('#start').setAttribute('aria-expanded',String(show));if(show)$('#start-menu button').focus();else $('#start').focus({preventScroll:true})}
const jokes=[['It looks like you’re exploring a resume. Excellent troubleshooting instinct.','Parece que estás explorando un currículum. Excelente instinto de diagnóstico.'],['Have you tried collecting evidence before restarting everything?','¿Has probado recopilar evidencia antes de reiniciar todo?'],['Coffee levels: nominal. Curiosity levels: suspiciously high.','Nivel de café: normal. Nivel de curiosidad: sospechosamente alto.'],['I am a robot. Rafael used to troubleshoot my colleagues.','Soy un robot. Rafael solía diagnosticar a mis colegas.']];
function desktop(){document.documentElement.lang=lang;$('#shortcuts').innerHTML=['home','experience','projects','game','resume','contact','recycle'].map(id=>`<button class="desktop-icon" data-open="${id}">${icon(app(id).icon)}<span class="shortcut-name">${label(id)}</span></button>`).join('');$('#sticky-text').innerHTML=t('Investigate.<br>Understand.<br>Fix it once.','Investigar.<br>Entender.<br>Resolver una vez.');$('#bot-toggle').innerHTML=robot();$('#bot-bubble').textContent=p(jokes[botIndex]);$('#language').textContent=lang.toUpperCase();$('#language').setAttribute('aria-label',t('Switch to Spanish','Cambiar a inglés'));$('#start-menu').innerHTML=`<div class="start-user">${robot()}<div>Rafael Rendon<small class="start-subtitle">${t('Your friendly troubleshooter','Tu aliado para resolver problemas')}</small></div></div><nav class="start-links">${apps.map(a=>`<button data-open="${a.id}">${icon(a.icon)}${a[lang]}</button>`).join('')}</nav><div class="start-foot"><span>RafaelOS · Personal Edition</span><button data-action="show-desktop">${t('Show desktop','Ver escritorio')}</button></div>`;for(const w of windows.values())renderWindow(w);tick()}
function tick(){const now=new Date();const opts={timeZone:'America/Bogota'};$('#clock').innerHTML=now.toLocaleTimeString(lang==='es'?'es-CO':'en-US',{...opts,hour:'2-digit',minute:'2-digit'})+'<br>'+now.toLocaleDateString('en-GB',{...opts,day:'2-digit',month:'2-digit',year:'numeric'});$('#gadget-date').textContent=now.toLocaleDateString(lang==='es'?'es-CO':'en-US',{...opts,weekday:'short',month:'short',day:'numeric'});const parts=new Intl.DateTimeFormat('en-GB',{...opts,hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).formatToParts(now);const h=Number(parts.find(x=>x.type==='hour').value),m=Number(parts.find(x=>x.type==='minute').value);$('.hour-hand').style.transform=`rotate(${h%12*30+m*.5}deg)`;$('.minute-hand').style.transform=`rotate(${m*6}deg)`}
function showDesktop(){const visible=[...windows.values()].filter(w=>!w.minimized);if(visible.length){visible.forEach(w=>{w.minimized=true;w.el.classList.add('hidden');w.el.classList.remove('active')});activeId=null;renderTasks()}else{const last=[...windows.values()].at(-1);if(last)activate(last.id)}$('#start-menu').hidden=true;$('#start').setAttribute('aria-expanded','false')}
document.addEventListener('click',e=>{
 const b=e.target.closest('button,a');if(!b)return;const el=b.closest('.window');const w=el?windows.get(el.id):null;
 if(b.dataset.open){open(b.dataset.open);$('#start-menu').hidden=true;$('#start').setAttribute('aria-expanded','false');return}
 if(b.dataset.nav&&w){w.view=b.dataset.nav;renderWindow(w);activate(w.id);w.el.querySelector('.sidebar .selected')?.scrollIntoView({block:'nearest',inline:'nearest'});return}
 if(b.dataset.task){const target=windows.get(b.dataset.task);if(activeId===target.id&&!target.minimized)minimize(target);else activate(target.id);return}
 if(b.dataset.control&&w){switch(b.dataset.control){case 'minimize':minimize(w);break;case 'close':w.el.remove();windows.delete(w.id);nextActive();$('#start').focus({preventScroll:true});break;case 'maximize':w.max=!w.max;w.el.classList.toggle('maximized',w.max);activate(w.id);break}return}
 if(b.id==='start'){setStart($('#start-menu').hidden);return}
 if(b.id==='language'){lang=lang==='en'?'es':'en';storage.set('rafaelos-language',lang);desktop();return}
 if(b.id==='bot-toggle'){botIndex=(botIndex+1)%jokes.length;$('#bot-bubble').textContent=p(jokes[botIndex]);return}
 if(b.id==='show-desktop'||b.dataset.action==='show-desktop'){showDesktop();return}
 if(b.dataset.mission!==undefined){game.mission=Number(b.dataset.mission);game.choice=null;game.finished=false;renderGame();w?.el.querySelector('.content').scrollTo(0,0);return}
 if(b.dataset.choice!==undefined){game.choice=Number(b.dataset.choice);renderGame();w?.el.querySelector('.feedback')?.scrollIntoView({block:'nearest'});return}
 switch(b.dataset.action){case 'mission-list':game.mission=null;game.choice=null;game.finished=false;renderGame();w?.el.querySelector('.content').scrollTo(0,0);break;case 'finish-mission':if(game.mission!==null&&game.choice===missions[game.mission].correct){completed=completeMission(completed,game.mission);storage.set('rafaelos-missions',JSON.stringify(completed));game.finished=true;renderGame();w?.el.querySelector('.content').scrollTo(0,0)}break;case 'reset-progress':completed=[];storage.set('rafaelos-missions','[]');renderGame();break}
});
document.addEventListener('pointerdown',e=>{
 const el=e.target.closest('.window');if(el&&activeId!==el.id)activate(el.id);
 if(!e.target.closest('#start-menu')&&!e.target.closest('#start')){$('#start-menu').hidden=true;$('#start').setAttribute('aria-expanded','false')}
 const bar=e.target.closest('.titlebar');if(!bar||e.target.closest('button')||compactLayout())return;const w=windows.get(el.id);if(w.max)return;const rect=el.getBoundingClientRect(),x=e.clientX,y=e.clientY;el.style.transform='none';el.style.left=rect.left+'px';el.style.top=rect.top+'px';el.style.marginLeft='0';bar.setPointerCapture(e.pointerId);
 const move=ev=>{el.style.left=Math.max(0,Math.min(innerWidth-rect.width,rect.left+ev.clientX-x))+'px';el.style.top=Math.max(0,Math.min($('#desktop').clientHeight-40,rect.top+ev.clientY-y))+'px'};
 const end=()=>{bar.removeEventListener('pointermove',move);bar.removeEventListener('pointerup',end);bar.removeEventListener('pointercancel',end)};bar.addEventListener('pointermove',move);bar.addEventListener('pointerup',end);bar.addEventListener('pointercancel',end);
});
document.addEventListener('dblclick',e=>{const bar=e.target.closest('.titlebar');if(bar&&!e.target.closest('button'))bar.querySelector('[data-control="maximize"]').click()});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!$('#start-menu').hidden)setStart(false)});
addEventListener('resize',()=>{if(!compactLayout())for(const w of windows.values()){if(w.max||w.minimized)continue;const r=w.el.getBoundingClientRect();if(r.right>innerWidth||r.left<0||r.bottom>$('#desktop').clientHeight){w.el.style.transform='none';w.el.style.marginLeft='0';w.el.style.left=Math.max(0,Math.min(r.left,innerWidth-r.width))+'px';w.el.style.top=Math.max(0,Math.min(r.top,$('#desktop').clientHeight-r.height))+'px'}}});
desktop();open('home');setInterval(tick,30000);
